head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = ""; // 발행회사코드
scwin.vIsurNm = ""; // 발행회사명
scwin.vIsuCd = ""; // 종목코드
scwin.vIsuNm = ""; // 종목명
scwin.vIsuAbbrv = ""; // 종목약명
scwin.v_SaveKind = ""; // 신규,수정 구분
scwin.vIsuNmChg = ""; // 종목명변경 Y/N
scwin.vIsuQtyChg = "";
// 세션정보를 얻기위한 함수사용

scwin.getPar, scwin.setPar;

scwin.TR_JOB;
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vSecuGrpId = parentWin.fr_SecuGrpId;

        //
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        // buttonSet.setDeleteInfo( btn_RecvIsuDel, fn_delete );     // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        /*
        if (vSecuGrpId == SECUGRP_ID_EN) {
        	txb_memo.disabled = false;
        	txb_memo.value = "(미입력시 '변경전' 값이 저장됩니다.)";
        } else {
        	txb_memo.disabled = true;
        }
         */
        // Parent Data
        scwin.v_SaveKind = parentWin.vIsuNmChgKind; // Transaction 구분: 신규(N), 수정(U)
        // v_UpdParam = parentWin.v_UpdItmIsurParam;    //변경상장내역 Param

        if (scwin.v_SaveKind === "N") {
            scwin.vBzProcsNo = ""; // 업무처리번호
            scwin.vIsuCd = parentWin.txb_SearchIsuCd2.getValue(); // 종목코드
            vAcptNo = parentWin.clickAcptNo; // 접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

            // 수정,삭제 버튼 비활성화
            btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_Update.setDisabled(true);
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
            btn_RecvIsuDel.setDisabled(true);
            btn_Dscl.setBackgroundImage("../img/btn_make_info_d.gif");
            btn_Dscl.setDisabled(true);
        } else {
            scwin.vBzProcsNo = parentWin.clickBzProcsNo; // 업무처리번호
            scwin.vIsuCd = parentWin.clickIsuCd; // 종목코드
            vAcptNo = parentWin.clickAcptNo; // 접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

            btn_Save.setBackgroundImage("../img/btn_save_d.gif");
            btn_Save.setDisabled(true);
            if (parentWin.clickDisclsYn === "Y") {
                btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
                btn_Update.setDisabled(true);
                btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
                btn_RecvIsuDel.setDisabled(true);
                btn_Dscl.setBackgroundImage("../img/btn_make_info_d.gif");
                btn_Dscl.setDisabled(true);
            }
        }

        // 데이터 조회
        await scwin.selectReadInit();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08026.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08026.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08026.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lce.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08026.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        // 저장메세지, 부모화면 Refresh, 화면 닫기
        $c.lce.fn_alertMsg('S');
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08026.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_CHG_LIST_DD_onclick
 * @description img_CHG_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHG_LIST_DD_onclick = function() {
    try {
        // 변경상장일 달력클릭
        popUpCalendar2(edt_CHG_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08026.img_CHG_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_RecvIsuDel_onclick
 * @description 「신청종목삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RecvIsuDel_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08026.btn_RecvIsuDel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 수량변경 Y/N

/**
 * @method
 * @name selectReadInit
 * @description 종목명변경 상장내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectReadInit = async function() {
    let url = "";
    let srvMethod = "";
    if (scwin.v_SaveKind === 'N') {
        srvMethod = "selectIsuNmChgForNew";
    } else if (scwin.v_SaveKind === 'U') {
        srvMethod = "selectIsuNmChgDetail";
    }
    url += "&SCREN_ID=" + "ULDSTF08026.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    url += "&SRCH_COM_CD=";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&ACPT_NO=" + vAcptNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.v_SaveKind === 'N') {
        txb_AFCHG_ISU_NM.setValue(dts_Isu.getCellData(1, "BFCHG_ISU_NM"));
        txb_AFCHG_ISU_ABBRV1.setValue(dts_Isu.getCellData(1, "BFCHG_ISU_ABBRV"));
        txb_AFCHG_ISU_ENG_NM.setValue(dts_Isu.getCellData(1, "BFCHG_ISU_ENG_NM"));
        txb_AFCHG_ISU_ENG_ABBRV1.setValue(dts_Isu.getCellData(1, "BFCHG_ISU_ENG_ABBRV"));
        // vAcptNo = parentWin.clickAcptNo;    //접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)
        // vAcptNo = dts_Isu.NameValue(1, "ACPT_NO");

    } else {
        // vAcptNo = parentWin.clickAcptNo;    //접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

        // vAcptNo = dts_Isu.NameValue(1, "ACPT_NO");

    }
    scwin.vIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.vIsurNm = dts_Isu.getCellData(1, "ISUR_NM");
    scwin.vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsuAbbrv = dts_Isu.getCellData(1, "ISU_ABBRV");
};

/**
 * @method
 * @name trs
 * @description 트랜잭션 처리 구분(저장,수정,삭제)
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    let srvMethod = "";
    let trsKind;
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        srvMethod = "insertIsuNmChgDtl";
        trsKind = TR_JOB_INSERT;
        scwin.setFormField();
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
        srvMethod = "updateIsuNmChgDtl";
        trsKind = TR_JOB_UPDATE;
        scwin.setFormField();
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
        srvMethod = "deleteIsuNmChgDtl";
        trsKind = TR_JOB_DELETE;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsKind,
    //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
    //     LD_MKT_TP_CD : "1",
    //     TRANSTR_EMP_NO : js_emp_no,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISUR_CD : scwin.vIsurCd,
    //     ISU_CD : scwin.vIsuCd,
    //     ACPT_NO : vAcptNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnChgList.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};
/**********************************************
 * 함수명 : fn_parentRefresh2()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
/*function fn_parentRefresh2() {
    //Parent 신청내역 화면 Refresh
	var parentWin = frame.Provider("../");
	parentWin.txb_SearchIsuCd2.value = vIsuCd;
	parentWin.txb_SearchIsuNm2.value = vIsuAbbrv;
	setObjectValue(parentWin.cmb_ISUR_CD2, vIsurCd);
	parentWin.fn_list_chglist_appl(vIsurCd, vIsuCd);
	parentWin.fn_list_chglist_sync();
}

 */

/**
 * @method
 * @name dupCheck
 * @description 종목 중복날짜 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dupCheck = async function() {
    const chgDd = edt_CHG_LIST_DD.getValue();
    let isNotDup = true;
    url += "&SCREN_ID=" + "ULDSTF08026.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISU_CD=" + scwin.vIsuCd + "&CHG_DD=" + chgDd + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_DupChk",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_DupChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_DupChk.getRowCount() > 0) {
        isNotDup = false;
        await $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (scwin.vIsuCd === "") {
        await $c.win.alert("[종목]이 조회되어 있지 않습니다.");
        return false;
    }
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    // Check Max Length
    if (txb_AFCHG_ISU_NM.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_NM.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_NM, 80, "한글종목명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ABBRV1.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ABBRV1.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ABBRV1, 40, "한글종목약명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ENG_NM.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_NM.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ENG_ABBRV1.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_ABBRV1.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_ABBRV1, 40, "영문종목약명")) return false;
        }
    }
    return true;
};

/**
 * @method
 * @name setFormField
 * @description 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 (현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함)
 * @returns {void}
 * @hidden N
 */
scwin.setFormField = function() {
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_NM.getValue())) === 1) {
        txb_AFCHG_ISU_NM.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ABBRV1.getValue())) === 1) {
        txb_AFCHG_ISU_ABBRV1.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_NM.getValue())) === 1) {
        txb_AFCHG_ISU_ENG_NM.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_ABBRV1.getValue())) === 1) {
        txb_AFCHG_ISU_ENG_ABBRV1.setValue("");
    }
};

/**
 * @method
 * @name save
 * @description 종목명 변경상장 내역 > 신규저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm() && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo === undefined || scwin.vBzProcsNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description 종목명 변경상장 내역 > 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm() && await scwin.dupCheck()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;

        /*if (vSecuGrpId == SECUGRP_ID_EN) {
        		fn_checkSave();
        }*/

        await scwin.trs(TRS_IDX_UPDATE);
    }
};

/**
         * @method
         * @name delete
         * @description 종목명 변경상장 내역 > 삭제
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    await scwin.trs(TRS_IDX_DELETE);
};

/**
 * @method
 * @name dscl
 * @description 수량변경 > 발행 및 상장내역 > 안내문 작성
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    const cCtnt = "";
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "68354";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = '1';
        arr[4] = scwin.getItmChgDisclsCtnt(); // ctnt
        arr[5] = txb_BFCHG_ISU_ABBRV.getValue(); // add  title

        $c.stf.copyDataSet(dts_Isu, param_dts_isu);

        // param_dts_mst.NameString(param_dts_mst.RowPosition, "TGT_NM") = Isur_nm ;

        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 25;
    const hgt = 785 + 40;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "상장지수증권 변경상장 안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;

    // 안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_chglist_sync();
};

/**
 * @method
 * @name getItmChgDisclsCtnt
 * @description 안내문작성 서식 (종목명변경)
 * @returns {void}
 * @hidden N
 */
scwin.getItmChgDisclsCtnt = function() {
    if (txb_AFCHG_ISU_NM.getValue().length > 0 || txb_AFCHG_ISU_ABBRV1.getValue().length > 0 || txb_AFCHG_ISU_ENG_NM.getValue().length > 0 || txb_AFCHG_ISU_ENG_ABBRV1.getValue().length > 0) {
        scwin.vIsuNmChg = "Y";
    } else {
        scwin.vIsuNmChg = "N";
    }
    if ((txb_CHG_ETN_ISU_QTY.getValue().length > 0 || txb_ETN_CONSLDT_RTO.getValue().length > 0 || txb_ETN_SPLIT_RTO.getValue().length > 0) &&
        (txb_CHG_ETN_ISU_QTY.getValue() > 0 || txb_ETN_CONSLDT_RTO.getValue() > 0 || txb_ETN_SPLIT_RTO.getValue() > 0)) {
        scwin.vIsuQtyChg = "Y";
    } else {
        scwin.vIsuQtyChg = "N";
    }
    let vCtnt = "";
    let vConsldtRto = txb_ETN_CONSLDT_RTO.getValue();
    let vSplitRto = txb_ETN_SPLIT_RTO.getValue();
    if (vConsldtRto === "0") vConsldtRto = "-";
    if (vSplitRto === "0") vSplitRto = "-";
    vCtnt += "[공시제목] 상장지수증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + scwin.vIsurNm + " 발행 상장지수증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "다음과 같이 " + txb_BFCHG_ISU_ABBRV.getValue() + "의 변경상장 내역을 알려드립니다.";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 변경내역";
    if (scwin.vIsuNmChg === "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 한글종목명";
        vCtnt += "\r\n";
        vCtnt += "    변경전: " + txb_BFCHG_ISU_NM.getValue() + " (약명 : " + txb_BFCHG_ISU_ABBRV.getValue() + ")";
        vCtnt += "\r\n";
        vCtnt += "    변경후: " + txb_AFCHG_ISU_NM.getValue() + " (약명 : " + txb_AFCHG_ISU_ABBRV1.getValue() + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += " - 영문종목명";
        vCtnt += "\r\n";
        vCtnt += "    변경전: " + txb_BFCHG_ISU_ENG_NM.getValue() + " (약명 : " + txb_BFCHG_ISU_ENG_ABBRV.getValue() + ")";
        vCtnt += "\r\n";
        vCtnt += "    변경후: " + txb_AFCHG_ISU_ENG_NM.getValue() + " (약명 : " + txb_AFCHG_ISU_ENG_ABBRV1.getValue() + ")";
    }
    if (scwin.vIsuQtyChg === "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 병합ㆍ분할";
        vCtnt += "\r\n";
        vCtnt += "    병합비율: " + vConsldtRto;
        vCtnt += "\r\n";
        vCtnt += "    분할비율: " + vSplitRto;
        vCtnt += "\r\n";
        vCtnt += "    변경전 상장수량: " + $c.stf.addComma(txb_ETN_ISU_QTY.getValue());
        vCtnt += "\r\n";
        vCtnt += "    변경후 상장수량: " + $c.stf.addComma(txb_CHG_ETN_ISU_QTY.getValue());
    }
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 변경 사유 : " + txb_CHG_RSN.getText();
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 변경상장일 : " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 년월일 포맷 맞춤 (안내문 작성에서 사용)
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_chglist_sync;
    fr_fn_list_sync();
};
